  render: () => <Box sx={{
    p: 4
  }}>
      <Stack spacing={4}>
        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            App Bar Actions
          </MuiTypography>
          <Stack direction="row" spacing={1}>
            <IconButton aria-label="notifications">
              <MaterialSymbol icon="notifications" />
            </IconButton>
            <IconButton aria-label="mail">
              <MaterialSymbol icon="mail" />
            </IconButton>
            <IconButton aria-label="settings">
              <MaterialSymbol icon="settings" />
            </IconButton>
          </Stack>
        </Box>

        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            Content Actions
          </MuiTypography>
          <Stack direction="row" spacing={1}>
            <IconButton color="primary" aria-label="add to favorites">
              <MaterialSymbol icon="favorite" />
            </IconButton>
            <IconButton color="primary" aria-label="share">
              <MaterialSymbol icon="share" />
            </IconButton>
            <IconButton color="error" aria-label="delete">
              <MaterialSymbol icon="delete" />
            </IconButton>
          </Stack>
        </Box>

        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            Different Sizes
          </MuiTypography>
          <Stack direction="row" spacing={2} alignItems="center">
            <IconButton size="small" color="primary" aria-label="small add">
              <MaterialSymbol icon="add" size="small" />
            </IconButton>
            <IconButton size="medium" color="primary" aria-label="medium add">
              <MaterialSymbol icon="add" />
            </IconButton>
            <IconButton size="large" color="primary" aria-label="large add">
              <MaterialSymbol icon="add" size="large" />
            </IconButton>
          </Stack>
        </Box>

        <Box>
          <MuiTypography variant="h6" sx={{
          mb: 2
        }}>
            Edge Positioning
          </MuiTypography>
          <Box sx={{
          display: 'flex',
          alignItems: 'center',
          gap: 2,
          width: 300,
          border: '1px dashed grey',
          p: 2
        }}>
            <IconButton edge="start" aria-label="start edge">
              <MaterialSymbol icon="add" />
            </IconButton>
            <MuiTypography sx={{
            flex: 1,
            textAlign: 'center'
          }}>Content</MuiTypography>
            <IconButton edge="end" aria-label="end edge">
              <MaterialSymbol icon="settings" />
            </IconButton>
          </Box>
        </Box>
      </Stack>
    </Box>,
  parameters: {
    layout: 'fullscreen'
  }
